const delay=(ms:number)=>new Promise(r=>setTimeout(r,ms));
async function overlap(f:Awaited<ReturnType<typeof cancellationFixture>>,jobs:(()=>Promise<any>)[],order=[0,1]){
 const blocker=h.connect('crm_h0_migration');await blocker.unsafe('begin');await blocker`select pg_advisory_xact_lock(hashtextextended(${f.b.opportunityId},31))`;
 const pending:Promise<any>[]=[];try{for(let i=0;i<order.length;i++){pending.push(jobs[order[i]!]!().then(value=>({ok:true,value}),error=>({ok:false,error:error.message})));let observed=0;for(let n=0;n<100;n++){observed=Number((await h.admin`select count(*)::int n from pg_stat_activity where usename='crm_h0_runtime' and wait_event_type='Lock'`)[0]!.n);if(observed>=i+1)break;await delay(10);}console.log('H4-014 observed PostgreSQL lock overlap',order,'queued',i+1,'sessions',observed);assert.ok(observed>=i+1);}await blocker.unsafe('rollback');return await Promise.all(pending);}finally{await blocker.unsafe('rollback');}}
for(const order of [[0,1],[1,0]])test('H4-014 C27 competing determinations with actual independent PG sessions '+order,async()=>{const f=await cancellationFixture(h,{amount:'200.00'}),q=await f.command(),b=await f.command({facts:facts(q,{cause:'provider'})});const r=await overlap(f,[()=>f.run(q),()=>f.run(b)],order);assert.equal(r.filter(x=>x.ok).length,1);assert.match(r.find(x=>!x.ok)!.error,/REVISION_CONFLICT:E2/);assert.equal((await f.see()).computed.right,order[0]===0?'100.00':'200.00');assert.equal((await f.see()).history.length,1);});
for(const order of [[0,1],[1,0]])test('H4-014 C27 equivalent concurrent replay independent sessions '+order,async()=>{const f=await cancellationFixture(h),q=await f.command();const r=await overlap(f,[()=>f.run(q),()=>f.run(q)],order);assert.equal(r.filter(x=>x.ok).length,2);assert.equal((await f.see()).history.length,1);assert.equal(r.filter(x=>x.value.replayed).length,1);});
for(const order of [[0,1],[1,0]])test('H4-014 C28 determination versus applied actual service date change '+order,async()=>{const f=await cancellationFixture(h,{amount:'200.00'}),q=await f.command(),change=await modificationFixture(h,f.conf);await change.run(await change.request([{id:change.partId,scope:change.scope,expectedScopeRevision:1,desired:{date:'2026-10-22'},aspects:['date'],dependencies:[]} ]));await change.run(await change.evaluate());await change.run(await change.approve());const apply=await change.apply();const before=await h.booking.read(await h.auth(),read,f.b.bookingId),r=await overlap(f,[()=>f.run(q),()=>change.run(apply)],order);if(order[0]===1){assert.equal(r.find(x=>!x.ok)!.error,'CANCELLATION_REVISION_CONFLICT:E2');assert.equal(await f.see(),null);}else{assert.equal(r.every(x=>x.ok),true);assert.equal((await h.cancellations.read(await h.auth(),read,f.b.bookingId,f.did,'right')).currentlyApplicable,false);}const current:any=await h.booking.read(await h.auth(),read,f.b.bookingId);assert.equal(current.booking.detail.services[0].date,'2026-10-22');assert.deepEqual(current.booking.accepted_detail,(before as any).booking.accepted_detail??(before as any).booking.detail);const next=await f.command({expectedRevision:order[0]===0?1:0,expectedScopeToken:await f.token(),facts:facts(q,{reference:{...q.facts!.reference!,date:localDate('2026-10-22')}})});const updated=await f.run(next);assert.equal(updated.result.computed.temporal.daysBefore,5);assert.equal(updated.result.computed.temporal.reference.date,'2026-10-22');});
for(const order of [[0,1],[1,0]])test('H4-014 C27 different exact obligation approvals compete no overwrite '+order,async()=>{const x=await appliedFixture(),alt=x.original.map(p=>({...p,amount:p.slot==='balance'?'50.00':'100.01'})),q2=await cancellationApplication(h,x.f,x.s.sid,alt);const r=await overlap(x.f,[()=>x.f.run(x.q),()=>x.f.run(q2)],order);assert.equal(r.filter(x=>x.ok).length,1);assert.equal(r.filter(x=>!x.ok).length,1);assert.equal((await x.f.see()).history.length,2);assert.equal((await h.observer`select count(*)::int n from crm_private.b06_cancellation_applications where determination_id=${x.f.did}::uuid`)[0]!.n,1);});
for(const table of ['b06_cancellation_determinations','b06_cancellation_operations','b06_cancellation_revisions'])test('H4-014 C29 injected write '+table+' exact rollback then retry',async()=>{const f=await cancellationFixture(h),q=await f.command(),before=await snap();await h.admin.unsafe("create function crm_private.f14_fault() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_F14_WRITE_FAULT';end$$");await h.admin.unsafe(`create trigger f14_fault before insert on crm_private.${table} for each row execute function crm_private.f14_fault()`);try{await assert.rejects(f.run(q));assert.deepEqual(await snap(),before);}finally{await h.admin.unsafe(`drop trigger f14_fault on crm_private.${table}`);await h.admin.unsafe('drop function crm_private.f14_fault()');}await f.run(q);assert.equal((await f.see()).revision,1);});
