test('H4-014 C29 deferred real COMMIT failure exact rollback and valid retry',async()=>{const x=await appliedFixture(),names=[...cancellationTables,'b05_schedule_revisions','b05_obligation_adjustments','b05_obligation_history','b05_coverage_evaluations'],before=await snap(h,names);await h.admin.unsafe("create function crm_private.f14_commit_fault() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_F14_COMMIT_FAULT';end$$");await h.admin.unsafe('create constraint trigger f14_commit_fault after insert on crm_private.b06_cancellation_operations deferrable initially deferred for each row execute function crm_private.f14_commit_fault()');try{await assert.rejects(x.f.run(x.q));assert.deepEqual(await snap(h,names),before);}finally{await h.admin.unsafe('drop trigger f14_commit_fault on crm_private.b06_cancellation_operations');await h.admin.unsafe('drop function crm_private.f14_commit_fault()');}await x.f.run(x.q);assert.equal((await x.f.see()).applied,true);});
