test('H4-014 C30 response lost strictly after real COMMIT recover durable result without second effect',async()=>{const x=await appliedFixture();const lost={begin:async(options:any,work:any)=>{await h.runtime.begin(options,work);throw new Error('SYNTHETIC_RESPONSE_LOST_AFTER_REAL_COMMIT');}} as unknown as typeof h.runtime;const adapter=new H4013CancellationAdapter(lost,h.f1,h.f2);await assert.rejects(adapter.apply(await h.auth(),write,x.q));assert.equal((await x.f.see()).applied,true);const before=await snap();assert.equal((await x.f.run(x.q)).replayed,true);assert.deepEqual(await snap(),before);});
